import{_ as n,o as t,c as r,a3 as i}from"./chunks/framework.B5WAEDB7.js";const g=JSON.parse('{"title":"Ich sehe eine Schaltfläche nicht","description":"Warum Bedienelemente in ApptiveGrid fehlen können und wie Sie die Ursache finden.","frontmatter":{"title":"Ich sehe eine Schaltfläche nicht","description":"Warum Bedienelemente in ApptiveGrid fehlen können und wie Sie die Ursache finden."},"headers":[],"relativePath":"fehlerbehebung/fehlende-schaltflaechen.md","filePath":"fehlerbehebung/fehlende-schaltflaechen.md","lastUpdated":1786518403000}'),a={name:"fehlerbehebung/fehlende-schaltflaechen.md"};function s(h,e,d,l,o,u){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="ich-sehe-eine-schaltflache-nicht" tabindex="-1">Ich sehe eine Schaltfläche nicht <a class="header-anchor" href="#ich-sehe-eine-schaltflache-nicht" aria-label="Permalink to &quot;Ich sehe eine Schaltfläche nicht&quot;">​</a></h1><p>„Bei mir sieht das anders aus als bei dir&quot; ist eine der häufigsten Rückfragen zu ApptiveGrid. Meist steckt kein Fehler dahinter.</p><div class="tip custom-block"><p class="custom-block-title">Das Grundprinzip</p><p>ApptiveGrid zeigt eine Funktion <strong>nur an, wenn Sie sie auch nutzen dürfen</strong>. Fehlt die Berechtigung, verschwindet die Schaltfläche — es erscheint keine Fehlermeldung und kein ausgegrauter Knopf.</p><p>Für Nutzer ohne die nötigen Rechte sieht die Oberfläche deshalb schlicht aufgeräumter aus.</p></div><h2 id="die-vier-haufigsten-ursachen" tabindex="-1">Die vier häufigsten Ursachen <a class="header-anchor" href="#die-vier-haufigsten-ursachen" aria-label="Permalink to &quot;Die vier häufigsten Ursachen&quot;">​</a></h2><h3 id="_1-·-ihre-rolle-im-space" tabindex="-1">1 · Ihre Rolle im Space <a class="header-anchor" href="#_1-·-ihre-rolle-im-space" aria-label="Permalink to &quot;1 · Ihre Rolle im Space&quot;">​</a></h3><p>Der häufigste Grund. Ihre <a href="/zusammenarbeit/rollen">Rolle</a> entscheidet, was Sie sehen:</p><table tabindex="0"><thead><tr><th>Rolle</th><th>Sie sehen keine Funktionen zum …</th></tr></thead><tbody><tr><td><strong>Ansehen</strong></td><td>Bearbeiten von Einträgen, Ändern der Struktur</td></tr><tr><td><strong>Bearbeiten</strong></td><td>Anlegen von Feldern, Ansichten, Formularen, Flows</td></tr><tr><td><strong>Managen</strong></td><td>Ändern von Tarif und Sitzplätzen</td></tr></tbody></table><p><strong>So prüfen Sie das:</strong> Öffnen Sie <strong>Space teilen</strong>. In der Liste <em>Geteilt mit</em> steht Ihre Rolle. Ist sie zu niedrig, bitten Sie eine Person mit der Rolle <em>Managen</em> oder den Eigentümer um eine Anpassung.</p><h3 id="_2-·-der-tarif" tabindex="-1">2 · Der Tarif <a class="header-anchor" href="#_2-·-der-tarif" aria-label="Permalink to &quot;2 · Der Tarif&quot;">​</a></h3><p>Manche Funktionen sind an den Tarif gebunden. Sie sind dann meist <strong>sichtbar, aber mit einem Upgrade-Hinweis versehen</strong> — bei Pro-Schritten im Flow-Editor etwa mit der Kennzeichnung <strong>Pro</strong>.</p><p>Klicken Sie auf die Funktion: Erscheint <em>Upgraden, um diese Funktion freizuschalten</em>, ist es der Tarif und nicht die Rolle.</p><h3 id="_3-·-der-kontext" tabindex="-1">3 · Der Kontext <a class="header-anchor" href="#_3-·-der-kontext" aria-label="Permalink to &quot;3 · Der Kontext&quot;">​</a></h3><p>Manche Funktionen erscheinen nur, wenn ihre Voraussetzung erfüllt ist:</p><table tabindex="0"><thead><tr><th>Sie vermissen …</th><th>Voraussetzung</th></tr></thead><tbody><tr><td><strong>Wert übernehmen</strong> oder <strong>Summe berechnen</strong> bei den Spaltentypen</td><td>Eine <a href="/grids/verknuepfungen">Verknüpfung</a> muss bestehen</td></tr><tr><td><strong>Summe berechnen</strong></td><td>Eine Spalte vom Typ <em>Mehrere Einträge verknüpfen</em></td></tr><tr><td>Kanban-Ansicht sinnvoll nutzbar</td><td>Eine Spalte vom Typ <em>Einzelauswahl</em></td></tr><tr><td>Kalender-Ansicht</td><td>Ein Datumsfeld</td></tr><tr><td>Karten-Ansicht</td><td>Ein Feld vom Typ <em>Adresse</em> oder <em>Geolokalisierung</em></td></tr><tr><td>Donut-Diagramm-Block</td><td>Eine Spalte vom Typ <em>Einzelauswahl</em></td></tr><tr><td>Summenkarte-Block</td><td>Eine numerische Spalte in der Ansicht</td></tr><tr><td><strong>Eintrag teilen</strong></td><td>Ein Formular auf diesem Grid</td></tr><tr><td>Freigabe-Optionen einer Seite</td><td>Ein erstellter Portal-Link</td></tr></tbody></table><h3 id="_4-·-sie-sind-im-falschen-modus" tabindex="-1">4 · Sie sind im falschen Modus <a class="header-anchor" href="#_4-·-sie-sind-im-falschen-modus" aria-label="Permalink to &quot;4 · Sie sind im falschen Modus&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Sie vermissen …</th><th>Prüfen Sie</th></tr></thead><tbody><tr><td>Bearbeitungsfunktionen auf einer Seite</td><td>Stehen Sie im Modus <em>Anwendung</em> statt <em>Editor</em>? Ist <em>Seite sperren</em> aktiv?</td></tr><tr><td>Blockeinstellungen</td><td>Ist der <em>Strukturmodus</em> eingeblendet und ein Block ausgewählt?</td></tr><tr><td>Spalten in einer Ansicht</td><td>Sind sie über <em>ausgeblendet</em> versteckt?</td></tr><tr><td>Einträge</td><td>Filtert die Ansicht sie heraus?</td></tr></tbody></table><h2 id="vorgehen-zur-eingrenzung" tabindex="-1">Vorgehen zur Eingrenzung <a class="header-anchor" href="#vorgehen-zur-eingrenzung" aria-label="Permalink to &quot;Vorgehen zur Eingrenzung&quot;">​</a></h2><ol><li><strong>Sieht eine Kollegin mit mehr Rechten die Funktion?</strong> Dann ist es die Rolle.</li><li><strong>Erscheint beim Klicken ein Upgrade-Hinweis?</strong> Dann ist es der Tarif.</li><li><strong>Fehlt die Funktion auch in einem neuen, leeren Grid?</strong> Dann ist es nicht der Kontext.</li><li><strong>Sind Sie in der richtigen Ansicht und im richtigen Modus?</strong></li></ol><h2 id="typische-falle" tabindex="-1">Typische Fälle <a class="header-anchor" href="#typische-falle" aria-label="Permalink to &quot;Typische Fälle&quot;">​</a></h2><p><strong>„Ich kann keine Spalte hinzufügen.&quot;</strong> Rolle <em>Bearbeiten</em> erlaubt das Ändern von Einträgen, nicht der Struktur. Sie brauchen <em>Managen</em>.</p><p><strong>„Ich sehe den Bereich Flows nicht.&quot;</strong> Prüfen Sie Rolle und Tarif — die Anzahl der Flows ist tarifabhängig.</p><p><strong>„Der Schalter am Flow lässt sich nicht umlegen.&quot;</strong> Einen <a href="/flows/was-ist-ein-flow#ein-und-ausschalten">Flow ein- oder auszuschalten</a> dürfen nur <em>Managen</em> und der Eigentümer. Bei <em>Bearbeiten</em> ist der Schalter sichtbar, aber gesperrt.</p><p><strong>„Ich kann kein Formular anlegen.&quot;</strong> Rolle prüfen; zusätzlich ist die Anzahl der Formulare je Space tarifabhängig.</p><p><strong>„Der Spaltentyp Wert übernehmen fehlt.&quot;</strong> Es gibt noch keine Verknüpfung im Grid. Legen Sie zuerst <em>Eintrag verknüpfen</em> an.</p><p><strong>„Ich kann den Tarif nicht ändern.&quot;</strong> Das kann nur der Eigentümer: <em>Der Eigentümer kann den Plan anpassen.</em></p><p><strong>„Der Kollege sieht mehr Spalten als ich.&quot;</strong> Sie arbeiten in unterschiedlichen Ansichten, oder in Ihrer Ansicht sind Spalten ausgeblendet. Ausgeblendete Spalten gelten je Ansicht, nicht je Person.</p><h2 id="wenn-nichts-davon-passt" tabindex="-1">Wenn nichts davon passt <a class="header-anchor" href="#wenn-nichts-davon-passt" aria-label="Permalink to &quot;Wenn nichts davon passt&quot;">​</a></h2><p>Melden Sie sich ab und wieder an — bei kurz zuvor geänderten Berechtigungen hilft das gelegentlich. Führt auch das nicht weiter, hilft der <strong>Chat</strong> in der Anwendung (<em>Chatten Sie mit uns</em>) weiter.</p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/zusammenarbeit/rollen">Rollen</a></li><li><a href="/fehlerbehebung/haeufige-fehlermeldungen">Häufige Fehlermeldungen</a></li><li><a href="/ansichten/spalten-verwalten">Spalten verwalten</a> — ausgeblendete Spalten</li></ul>',30)])])}const m=n(a,[["render",s]]);export{g as __pageData,m as default};
